import {regions,nodeAt,replaceRegionText} from '../../authoring/document.mjs';
import {renderBody,stable} from '../../hub-cms/body.mjs';
// Private DOM annotations only; accepted public renderer/generation stays unchanged.
export function bindCanvas(document,value,presentation,onSelect){const scope=[...document.querySelectorAll('.article-copy')],elements=[...document.querySelectorAll('*')].filter(e=>scope.some(root=>root===e||root.contains(e))),used=new Set(),bound=[];const expected=node=>{const holder=document.createElement('template');holder.innerHTML=renderBody({type:'doc',content:[node]},presentation);return holder.content.firstElementChild;};
 const candidates=Object.entries(value.body.slots).flatMap(([slot,doc])=>regions(doc).map(r=>({...r,slot})));
 for(const region of [...candidates.filter(r=>r.kind==='protected'),...candidates.filter(r=>r.kind!=='protected')]){let sample;try{sample=expected(region.node);}catch{continue;}if(!sample)continue;const target=elements.find(e=>!used.has(e)&&!e.closest('[data-authoring-protected]')&&e.outerHTML===sample.outerHTML);if(!target)continue;used.add(target);target.dataset.authoringRegion=region.slot+':'+region.path.join('.');if(region.kind==='protected'){target.dataset.authoringProtected='true';target.title='Protected technical content · read only';}else{target.dataset.authoringEditable=String(region.editable);target.tabIndex=0;target.setAttribute('role','button');target.setAttribute('aria-label',region.editable?'Edit '+region.kind+' in private draft':'Formatted '+region.kind+' · use structured editor');const select=event=>{event.preventDefault();event.stopPropagation();onSelect(region);};target.addEventListener('click',select,true);target.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' ')select(event);});}bound.push({...region,element:target});}
 const style=document.createElement('style');style.dataset.authoringOverlay='true';style.textContent='[data-authoring-editable]{cursor:pointer}[data-authoring-editable]:hover,[data-authoring-editable]:focus{outline:2px solid #b3934f;outline-offset:5px}[data-authoring-protected]{outline:1px dashed #b3934f;outline-offset:3px}';document.head.append(style);for(const type of ['click','keydown','beforeinput'])document.addEventListener(type,event=>{if(event.target.closest?.('[data-authoring-protected]')){event.preventDefault();event.stopImmediatePropagation();}else if(type==='click'&&event.target.closest?.('a'))event.preventDefault();},true);return bound;
}
export function applyCanvasText(current,base,region,text){if(stable(current.body)!==stable(base.body))throw Error('Draft changed since canvas opened; refresh the canvas.');const result=structuredClone(current);result.body.slots[region.slot]=replaceRegionText(current.body.slots[region.slot],region.path,text);return {content:result,node:nodeAt(result.body.slots[region.slot],region.path)};}
